import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        s = next(iterator)
        n = len(s)

        if n % 2 != 0:
            results.append("NO")
            continue

        target = n // 2

        open_count = 0
        close_count = 0
        balance = 0
        possible = True

        for char in s:
            if char == '(':
                open_count += 1
                balance += 1
            elif char == ')':
                close_count += 1
                balance -= 1
            else:
                pass

            if balance < 0:
                possible = False
                break

        if not possible:
            results.append("NO")
            continue

        if open_count > target or close_count > target:
            results.append("NO")
            continue

        remaining = n - open_count - close_count
        needed_open = target - open_count
        needed_close = target - close_count

        if needed_open < 0 or needed_close < 0:
            results.append("NO")
            continue

        if needed_open + needed_close != remaining:
            results.append("NO")
            continue

        balance = 0
        current_open = open_count
        current_close = close_count

        for char in s:
            if char == '(':
                    balance += 1
            elif char == ')':
                balance -= 1
            else:
                if current_open < target:
                    balance += 1
                    current_open += 1
                else:
                    balance -= 1
                    current_close += 1

            if balance < 0:
                possible = False
                balance = 0
                break

        if possible and balance == 0:
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
